<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue';
import {Home,Layers3,Gamepad2,Server,Compass,Plus,Settings,HelpCircle,ChevronDown,ChevronRight,ArrowUpRight,ArrowRight,Download,RefreshCw,LogIn,LogOut,Play,Square,Minus,X,Maximize2,FolderOpen,Box,Globe,BookOpen,Terminal,ShieldCheck,Activity,Search,Copy,ExternalLink,Package,Cloud,Monitor,Check,Pause,RotateCcw,Sparkles,GitBranch} from '../../packages/ui/icons';
import {useInteractions} from '../../packages/ui/interactions';
import '../../packages/ui/motion.css';
import SelectControl from '../../packages/ui/SelectControl.vue';
import LoaderMark from '../../packages/ui/LoaderMark.vue';
import buildInfo from '../../packages/shared/build.json';
import {useAssignments,type Assignment} from './assignments';
import {features} from '../../packages/shared/features';
import {searchUrl,versionsUrl,projectUrl,normalizeHits,normalizeVersions,providerJson} from '../../packages/shared/content.mjs';
import WorldArt from '../../packages/ui/WorldArt.vue';
import HomeWorkspace from './HomeWorkspace.vue';
import InstanceWorkspace from './InstanceWorkspace.vue';
import LoadingCards from '../../packages/ui/LoadingCards.vue';
import {snapshot,publicLoading,currentEvent,preferences,refreshPublic,savePreferences,native,isDesktop,openExternal,eventOptions,preview,latest,links} from '../../packages/shared/client';
useInteractions();
const section=ref('dashboard'),modal=ref<string|null>(null),busy=ref(false),error=ref(''),message=ref(''),engineReady=ref(false);
const activeInstanceId=ref<string|null>(null),workspaceRef=ref<any>(null);
const activeInstance=computed(()=>instances.value.find(i=>i.id===activeInstanceId.value)||null);
const appUpdate=ref<any>({state:'waiting'}),coreCapabilities=ref<any>(null),minecraftPrompt=ref<any>(null);
let removeMinecraftListener:(()=>void)|null=null;
const bootVisible=ref(true),interfaceReady=ref(false),engineStarting=ref(isDesktop),startupError=ref(''),searching=ref(false),hasSearched=ref(false);
const instances=ref<any[]>([]),localServers=ref<any[]>([]),hosted=ref<any[]>([]),jobs=ref<any[]>([]),account=ref<any>(null),minecraft=ref<any[]>([]),entitlements=ref<any[]>([]);
const {items:assignments,loading:assignmentsLoading,error:assignmentsError,refresh:loadAssignments}=useAssignments(account);
const assignmentTarget=ref<Assignment|null>(null),releaseConsent=ref(false);
const libraryQuery=ref(''),libraryView=ref(localStorage.getItem('solara:library-view')==='list'?'list':'grid');
const visibleInstances=computed(()=>instances.value.filter(i=>`${i.name} ${i.gameVersion} ${i.loader}`.toLowerCase().includes(libraryQuery.value.trim().toLowerCase())));
watch(libraryView,value=>localStorage.setItem('solara:library-view',value));
const versions=ref<any[]>([]),selectedInstance=ref<any>(null),logs=ref(''),serverTab=ref('local'),serviceFilter=ref('all'),query=ref(''),results=ref<any[]>([]),contentType=ref('mod');
const selectedContent=ref<any>(null),packVersionsLoading=ref(false);let searchController:AbortController|null=null,packController:AbortController|null=null;
const create=ref({name:'',gameVersion:'',loader:'vanilla',loaderVersion:''});const serverForm=ref({name:'',version:'',javaPath:'java',memory:2048,port:25565,eula:false});
const loaderChoices=ref<any[]>([]),loaderLoading=ref(false),loaderError=ref('');let loaderRequest=0;
const assignment=ref({name:'',endpoint:'',port:25565,serverId:'',consent:false});const nativeSettings=ref({memory:4096,javaPath:'java',discord:false});const editForm=ref({name:'',memory:4096,javaPath:''});
const availableLoaders=computed(()=>coreCapabilities.value?.loaders?loaderInfo.filter(loader=>coreCapabilities.value.loaders.includes(loader.id)):loaderInfo);
const tabs=[{id:'dashboard',label:'Dashboard',short:'Home',icon:Home},{id:'launcher',label:'Minecraft launcher',short:'Minecraft',icon:Gamepad2},{id:'services',label:'Solara services',short:'Services',icon:Layers3},{id:'servers',label:'Your servers',short:'Servers',icon:Server},{id:'explore',label:'Explore mods and modpacks',short:'Explore',icon:Compass}];
function projectIcon(item:any){const value=(item.name||'').toLowerCase();if(value.includes('auth'))return ShieldCheck;if(value.includes('host'))return Server;if(value.includes('network'))return Globe;if(value.includes('tool'))return Terminal;return Box}
function statusTone(value:string|null|undefined){const s=(value||'').toLowerCase();if(['operational','online','connected'].includes(s))return 'online';if(['maintenance','degraded','partial outage'].includes(s))return 'warning';if(['offline','outage','unavailable','major outage'].includes(s))return 'offline';return 'unknown'}
const projects=computed(()=>snapshot.value.data?.projects||[]);const services=computed(()=>snapshot.value.data?.services||[]);const publicReleases=computed(()=>snapshot.value.data?.releases||[]);
const title=computed(()=>tabs.find(t=>t.id===section.value)?.label||'Settings');const filteredServices=computed(()=>services.value.filter((s:any)=>serviceFilter.value==='all'||s.category===serviceFilter.value));
const selectedLog=ref<any>(null);let removeNativeListener:(()=>void)|null=null;const contentPane=ref<HTMLElement|null>(null);let lastFocus:HTMLElement|null=null;const loaderInfo=[{id:'vanilla',name:'Vanilla',hint:'The original experience'},{id:'fabric',name:'Fabric',hint:'Light and flexible'},{id:'forge',name:'Forge',hint:'A modding classic'},{id:'quilt',name:'Quilt',hint:'Community focused'},{id:'neoforge',name:'NeoForge',hint:'Build something new'}];
let timer:ReturnType<typeof setInterval>|null=null,publicTimer:ReturnType<typeof setInterval>|null=null,toastTimer:ReturnType<typeof setTimeout>|null=null;
function toast(text:string){message.value=text;if(toastTimer)clearTimeout(toastTimer);toastTimer=setTimeout(()=>message.value='',7000)}
async function run(fn:()=>Promise<unknown>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=String(e instanceof Error?e.message:e)}finally{busy.value=false}}
async function navigate(id:string){if(workspaceRef.value&&!await workspaceRef.value.canLeave())return;activeInstanceId.value=null;section.value=id;error.value='';contentPane.value?.scrollTo({top:0,behavior:'instant'});if(id==='servers'&&serverTab.value==='hosted')void loadHosted()}
async function openInstance(instance:any){if(workspaceRef.value&&!await workspaceRef.value.canLeave())return;activeInstanceId.value=instance.id;section.value='launcher';contentPane.value?.scrollTo({top:0,behavior:'instant'});}

function close(){modal.value=null;error.value=''}
function show(kind:string){modal.value=kind;error.value=''}
async function external(url:string){try{await openExternal(url)}catch(e){toast(String(e))}}
async function windowAction(action:string){await run(()=>native('window_action',{action}))}
async function onTitlebarMouseDown(e:MouseEvent){if(e.buttons===1&&(e.target as HTMLElement)?.closest('button,input,select,textarea,a')===null){if(isDesktop){try{const{getCurrentWindow}=await import('@tauri-apps/api/window');await getCurrentWindow().startDragging()}catch{void native('start_dragging').catch(()=>{})}}}}
function onTitlebarDblClick(e:MouseEvent){if((e.target as HTMLElement)?.closest('button')===null){void windowAction('maximize')}}
const scenes=['forest-valley','alpine-lake','coastal-hamlet','canyon-settlement','moss-cave','workshop'];
function instanceScene(inst:any):string{const name=inst?.name||'';let hash=0;for(let i=0;i<name.length;i++){hash=(hash<<5)-hash+name.charCodeAt(i);hash|=0}return scenes[Math.abs(hash)%scenes.length]}
function instanceArtSrc(inst:any):string{return `/art/${instanceScene(inst)}-v1-small.webp`}
function formatDownloads(num:number|null|undefined):string{if(!num||num<=0)return '';if(num>=1_000_000)return (num/1_000_000).toFixed(1).replace(/\.0$/,'')+'M';if(num>=1_000)return (num/1_000).toFixed(1).replace(/\.0$/,'')+'k';return String(num)}
async function plus(){if(section.value==='servers'){show('create-server');if(!versions.value.length)void loadVersions()}else{show('create-instance');if(!versions.value.length)void loadVersions()}}
async function pollLocal(){if(!isDesktop||!engineReady.value)return;try{const s=await native('launcher_snapshot');instances.value=s.instances;localServers.value=s.localServers;jobs.value=s.downloads;minecraft.value=s.minecraftAccounts;appUpdate.value=await native('app_update_status')||{state:'waiting'};if(selectedLog.value)logs.value=await native('local_server_logs',{id:selectedLog.value.id});}catch(e){toast(String(e))}}
async function loadLoaderVersions(){const token=++loaderRequest;loaderChoices.value=[];loaderError.value='';if(!isDesktop||create.value.loader==='vanilla'||!create.value.gameVersion){loaderLoading.value=false;return}loaderLoading.value=true;try{const choices=await native('loader_versions',{gameVersion:create.value.gameVersion,loader:create.value.loader});if(token===loaderRequest)loaderChoices.value=choices}catch(e){if(token===loaderRequest)loaderError.value=String(e)}finally{if(token===loaderRequest)loaderLoading.value=false}}
watch(()=>[create.value.gameVersion,create.value.loader],()=>{create.value.loaderVersion='';void loadLoaderVersions()});
async function loadVersions(){await run(async()=>{versions.value=await native('minecraft_versions');if(!create.value.gameVersion)create.value.gameVersion=versions.value.find(v=>v.type==='release')?.id||'';if(!serverForm.value.version)serverForm.value.version=create.value.gameVersion})}
async function prepareInterface(){
  let deadline:ReturnType<typeof setTimeout>|undefined;
  const artwork=(src:string)=>new Promise<void>(resolve=>{const img=new Image();img.onload=()=>{void img.decode().catch(()=>{}).then(()=>resolve())};img.onerror=()=>resolve();img.src=src});
  try{await Promise.race([Promise.all([artwork('/logo.svg'),document.fonts.ready.catch(()=>{})]),new Promise<void>(resolve=>{deadline=setTimeout(resolve,8000)})])}finally{if(deadline)clearTimeout(deadline);interfaceReady.value=true}
}
async function init(){
  void refreshPublic();if(!isDesktop)return;
  engineStarting.value=true;startupError.value='';error.value='';
  try{await native('initialize_launcher');coreCapabilities.value=await native('launcher_capabilities');nativeSettings.value=await native('launcher_settings');engineReady.value=true;await pollLocal();if(timer)clearInterval(timer);timer=setInterval(()=>void pollLocal(),3000);void native('solara_profile').then(value=>account.value=value).catch(e=>toast(String(e)))}
  catch(e){engineReady.value=false;startupError.value=String(e instanceof Error?e.message:e);error.value='Local launcher could not start: '+startupError.value}
  finally{engineStarting.value=false}
}
watch([interfaceReady,engineStarting],()=>{if(interfaceReady.value&&!engineStarting.value&&!startupError.value)bootVisible.value=false});
function retryStartup(){bootVisible.value=true;void init()}

async function signIn(){let signed=false;await run(async()=>{account.value=await native('solara_sign_in');signed=true;toast('Signed in to Solara. Your Minecraft account is separate.')});if(signed)await loadHosted()}
async function signOut(){await run(async()=>{try{await native('solara_sign_out')}finally{account.value=null;hosted.value=[];entitlements.value=[];}toast('Solara session signed out. Minecraft accounts are unchanged.')})}
async function mcSignIn(){await run(async()=>{try{await native('minecraft_sign_in');await pollLocal();toast('Minecraft account verified and saved on this device.')}finally{minecraftPrompt.value=null;if(modal.value==='minecraft-login')close();}})}
async function mcLogout(id:string){await run(async()=>{await native('minecraft_sign_out',{id});await pollLocal()})}
async function createInstance(){await run(async()=>{await native('create_instance',{...create.value});close();await pollLocal();section.value='launcher';toast('Instance installation queued. Follow its progress in Downloads.')})}
async function retryInstall(instance:any){await run(async()=>{await native('retry_instance',{id:instance.id});await pollLocal();toast('Installation queued. Your worlds are kept.');})}
async function launch(instance:any){await run(async()=>{await native('launch_instance',{id:instance.id});await pollLocal();toast('Minecraft launch requested. Follow the local process state.')})}
async function stopGame(instance:any){await run(async()=>{await native('stop_instance',{id:instance.id});await pollLocal()})}
async function editInstance(instance:any){selectedInstance.value=instance;editForm.value={name:instance.name,memory:instance.memory||nativeSettings.value.memory,javaPath:instance.javaPath||''};show('edit-instance')}
async function saveInstance(){await run(async()=>{await native('edit_instance',{id:selectedInstance.value.id,...editForm.value});close();await pollLocal()})}
async function instanceLogs(instance:any){await run(async()=>{logs.value=await native('instance_logs',{id:instance.id});selectedLog.value=null;show('logs')})}
async function saveServer(){await run(async()=>{await native('create_local_server',{...serverForm.value});close();await pollLocal();section.value='servers';toast('Local server setup queued. Files stay on this device.')})}
async function localPower(s:any,action:string){await run(async()=>{await native('local_server_action',{id:s.id,action});await pollLocal()})}
async function localLogs(s:any){await run(async()=>{selectedLog.value=s;logs.value=await native('local_server_logs',{id:s.id});show('logs')})}
async function loadHosted(){if(!account.value)return;await run(async()=>{const d=await native('solara_request',{method:'GET',path:'/v1/launcher/servers',body:null});hosted.value=d.servers||[]})}
async function remotePower(s:any,action:string){await run(async()=>{await native('solara_request',{method:'POST',path:`/v1/launcher/servers/${encodeURIComponent(s.id)}/power`,body:{action}});toast('Panel accepted the power request.');});await loadHosted()}
function beginAssignment(){assignmentTarget.value=null;assignment.value={name:'',endpoint:'',port:25565,serverId:localServers.value.length===1?localServers.value[0].id:'',consent:false};show('assignment')}
function editAssignment(item:Assignment){assignmentTarget.value=item;assignment.value={name:item.name,endpoint:item.endpoint,port:item.port,serverId:item.serverId,consent:false};show('edit-assignment')}
function beginRelease(item:Assignment){assignmentTarget.value=item;releaseConsent.value=false;show('release-assignment')}
async function saveAssignment(){
  const target=assignmentTarget.value,editing=modal.value==='edit-assignment';
  if(editing&&!target)return;
  await run(async()=>{await native('solara_request',{method:editing?'PATCH':'POST',path:'/v1/launcher/assignments'+(editing?'/'+target!.id:''),body:editing?{endpoint:assignment.value.endpoint,port:assignment.value.port,consent:assignment.value.consent}:{...assignment.value}});close();toast(editing?'Server address updated.':'Server address request completed.');});await loadAssignments();
}
async function copyAssignment(item:Assignment){if(!item.hostname)return;await run(async()=>{await navigator.clipboard.writeText(item.hostname!);toast('Server address copied.')})}
async function releaseAssignment(){
  const target=assignmentTarget.value;if(!target||!releaseConsent.value)return;
  await run(async()=>{await native('solara_request',{method:'DELETE',path:'/v1/launcher/assignments/'+target.id,body:null});close();toast('Server address released. Your local server files stay on this device.');});await loadAssignments();
}
watch([section,serverTab,()=>account.value?.id],()=>{if(section.value==='servers'&&serverTab.value==='hosting')void loadAssignments()});

async function searchContent(){
  if(searching.value)return;
  searchController?.abort();const controller=new AbortController();searchController=controller;
  const kind=contentType.value;searching.value=true;error.value='';
  try{const data=await providerJson(searchUrl(query.value,kind),AbortSignal.any([controller.signal,AbortSignal.timeout(10000)]));if(searchController!==controller)return;results.value=normalizeHits(data,kind);hasSearched.value=true}
  catch(e){if(!controller.signal.aborted)error.value=String(e instanceof Error?e.message:e)}
  finally{if(searchController===controller){searchController=null;searching.value=false}}
}
watch(contentType,()=>{searchController?.abort();searchController=null;searching.value=false;results.value=[];hasSearched.value=false;error.value='';void searchContent();});
watch(section,sec=>{if(sec==='explore'&&!results.value.length&&!searching.value)void searchContent()});
const eligibleTargetInstances=computed(()=>{const kind=selectedContent.value?.kind;if(!kind||kind==='modpack')return [];return kind==='mod'?instances.value.filter(i=>i.loader&&i.loader!=='vanilla'):instances.value});
async function installContent(hit:any){
  const kind=hit.project_type;
  if(kind!=='modpack'){
    const targets=kind==='mod'?instances.value.filter(i=>i.loader&&i.loader!=='vanilla'):instances.value;
    if(!targets.length){toast(kind==='mod'?'Create a Fabric or Quilt instance before adding mods.':'Create an instance before adding mods or packs.');return}
    selectedContent.value={project:hit,kind,instanceId:targets[0]?.id||'',versionId:'',versions:[],error:''};show('install-content');return;
  }
  selectedContent.value={project:hit,kind,instanceId:'',versionId:'',versions:[],error:''};show('install-content');void loadPackVersions();
}
async function loadPackVersions(){
  const draft=selectedContent.value;if(!draft||draft.kind!=='modpack')return;
  packController?.abort();const controller=new AbortController();packController=controller;packVersionsLoading.value=true;draft.error='';
  try{const data=await providerJson(versionsUrl(draft.project.project_id),AbortSignal.any([controller.signal,AbortSignal.timeout(10000)]));if(packController!==controller)return;const supported=Array.isArray(coreCapabilities.value?.loaders)?new Set([...coreCapabilities.value.loaders,'minecraft']):null;draft.versions=normalizeVersions(data,draft.project.project_id).filter((v:any)=>!supported||!v.loaders||v.loaders.split(', ').some((l:string)=>supported.has(l.toLowerCase())));draft.versionId=(draft.versions.find((v:any)=>v.type==='release')||draft.versions[0])?.id||''}
  catch(e){if(!controller.signal.aborted)draft.error=String(e instanceof Error?e.message:e)}
  finally{if(packController===controller){packController=null;packVersionsLoading.value=false}}
}
async function confirmInstall(){
  const draft=selectedContent.value;if(!draft||!engineReady.value)return;
  if(draft.kind==='modpack'&&!draft.versions.some((v:any)=>v.id===draft.versionId))return;
  if(draft.kind!=='modpack'&&!eligibleTargetInstances.value.some(i=>i.id===draft.instanceId))return;
  await run(async()=>{await native('install_content',{instanceId:draft.kind==='modpack'?null:draft.instanceId,projectId:draft.project.project_id,contentType:draft.kind,versionId:draft.kind==='modpack'?draft.versionId:null});if(modal.value==='install-content'&&selectedContent.value===draft)close();toast(draft.kind==='modpack'?'Modpack installation queued. Follow its progress in Downloads.':'Content installation requested for your instance.');await pollLocal();if(draft.kind==='modpack'&&section.value==='explore')navigate('launcher')});
}
watch(modal,value=>{if(value!=='minecraft-login'&&minecraftPrompt.value){void native('cancel_minecraft_sign_in').catch(()=>{});minecraftPrompt.value=null;}if(value!=='install-content'){packController?.abort();packController=null;packVersionsLoading.value=false;selectedContent.value=null}});

async function downloadAction(job:any,action:string){if(action==='cancel'){try{await native('download_action',{id:job.id,action});await pollLocal()}catch(e){error.value=String(e)}return}await run(async()=>{await native('download_action',{id:job.id,action});await pollLocal()})}
async function saveNative(){await run(async()=>{await native('save_launcher_settings',{...nativeSettings.value});toast('Local launcher preferences saved.')})}
async function checkUpdates(){await run(async()=>{const r=await native('check_update');toast(r.available?'An update is available. Solara will apply it automatically when your games and downloads are finished.':'You are up to date.');})}

async function loadEntitlements(){await run(async()=>{const d=await native('solara_request',{method:'GET',path:'/v1/launcher/entitlements',body:null});entitlements.value=d.entitlements||[];show('beta')})}
watch(engineReady,v=>{if(v&&['create-instance','create-server'].includes(modal.value||''))void loadVersions()});watch(preferences,()=>savePreferences(),{deep:true});watch(modal,async v=>{if(v!=='logs')selectedLog.value=null;if(v){lastFocus=document.activeElement as HTMLElement;await nextTick();(document.querySelector('.modal input,.modal [role=combobox],.modal .close') as HTMLElement)?.focus();}else{lastFocus?.focus();}});
function trapDialog(e:KeyboardEvent){if(e.key==='Escape'){close();return};if(e.key!=='Tab')return;const nodes=[...document.querySelectorAll<HTMLElement>('.modal button:not(:disabled),.modal input:not(:disabled),.modal select:not(:disabled),.modal a[href]')].filter(el=>el.offsetParent!==null&&el.tabIndex!==-1);const first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}
onMounted(()=>{if(isDesktop)void import('@tauri-apps/api/event').then(async({listen})=>{removeNativeListener=await listen('shutdown-error',event=>toast(String(event.payload)));removeMinecraftListener=await listen('minecraft-login-code',event=>{minecraftPrompt.value=event.payload;show('minecraft-login')})});void prepareInterface();void init();publicTimer=setInterval(()=>void refreshPublic(),60000)});onUnmounted(()=>{searchController?.abort();packController?.abort();removeNativeListener?.();removeMinecraftListener?.();if(timer)clearInterval(timer);if(publicTimer)clearInterval(publicTimer);if(toastTimer)clearTimeout(toastTimer)});
async function copyAddress(){await navigator.clipboard.writeText(snapshot.value.data.network.address);toast('Server address copied.')}
const date=new Intl.DateTimeFormat('en-IN',{weekday:'long',day:'numeric',month:'long'}).format(new Date());
</script>
<template>
<div class="shell" :style="{'--accent':preferences.accent||currentEvent.accent}" :data-reduced-motion="preferences.motion">
  <div class="titlebar" :inert="modal?true:undefined" data-tauri-drag-region @mousedown="onTitlebarMouseDown" @dblclick="onTitlebarDblClick"><span class="name" data-tauri-drag-region><img src="/logo.svg" alt="">solara<span class="titlebar-edition">launcher</span><span class="titlebar-build">{{buildInfo.publicVersion||'PREVIEW'}}</span></span><div class="window-buttons"><button title="Minimize" aria-label="Minimize" :disabled="!isDesktop" @click="windowAction('minimize')"><Minus/></button><button title="Maximize or restore" aria-label="Maximize or restore" :disabled="!isDesktop" @click="windowAction('maximize')"><Maximize2/></button><button title="Close Solara" aria-label="Close Solara" :disabled="!isDesktop" @click="windowAction('close')"><X/></button></div></div>
  <aside class="sidebar" :inert="modal||bootVisible?true:undefined"><div class="rail-brand"><img class="brand-logo" src="/logo.svg" alt="Solara"><span>SOLARA</span></div><nav aria-label="Main navigation"><button v-for="t in tabs" :key="t.id" :data-tooltip="t.label" :aria-label="t.label" :aria-current="section===t.id?'page':undefined" :class="{active:section===t.id}" @click="navigate(t.id)"><component :is="t.icon"/><span class="nav-label">{{t.short}}</span></button><button class="nav-plus" :data-tooltip="section==='servers'?'Create local server':'Create Minecraft instance'" :aria-label="section==='servers'?'Create local server':'Create Minecraft instance'" @click="plus"><Plus/></button></nav><div class="bottom-nav"><button data-tooltip="Help and support" aria-label="Help and support" @click="external(links.support)"><HelpCircle/></button><button data-tooltip="Settings" aria-label="Settings" :class="{active:section==='settings'}" @click="navigate('settings')"><Settings/></button></div></aside>
  <div class="main-column" :inert="modal||bootVisible?true:undefined"><header class="app-topbar" data-tauri-drag-region @mousedown="onTitlebarMouseDown" @dblclick="onTitlebarDblClick"><div class="toolbar-location"><button class="toolbar-home" title="Go to home" aria-label="Go to home" @click="navigate('dashboard')"><Home/></button><span class="toolbar-divider"></span><span class="toolbar-current"><component :is="tabs.find(t=>t.id===section)?.icon||Settings"/><strong>{{activeInstance?activeInstance.name:section==='dashboard'?'Home':section==='launcher'?'Minecraft':title}}</strong></span></div><div class="top-right"><button class="toolbar-downloads" aria-label="Open downloads" title="Open downloads" @click="show('downloads')"><Download/><span v-if="jobs.some(j=>['running','queued','downloading'].includes(j.status))" class="toolbar-download-dot"></span></button><span v-if="busy||searching||packVersionsLoading" class="app-busy" aria-label="An operation is in progress"></span><span class="pill"><span class="dot"></span>{{account?'Signed in':'Guest mode'}}</span><button v-if="!account" class="signin" :disabled="busy" @click="signIn"><LogIn/> Sign in to Solara</button><button v-else class="signin" @click="show('account')"><ShieldCheck/>{{account.name||account.username}} <ChevronDown/></button></div></header>
  <main ref="contentPane" class="app-content" :aria-label="title"><div :key="section" class="section-view">
    <div v-if="error" class="banner error" role="alert" style="margin-bottom:20px">{{error}}</div>
    <HomeWorkspace v-if="section==='dashboard'" :instances="instances" :projects="projects" :services="services" :account="account" :loading="publicLoading" :api-state="snapshot.state" @open-instance="openInstance" @create="plus" @navigate="navigate" @external="external" @refresh="refreshPublic"/>
    <template v-if="section==='launcher'">
      <InstanceWorkspace v-if="activeInstance" ref="workspaceRef" :instance="activeInstance" :jobs="jobs" :account-ready="minecraft.some(a=>a.active)" :parent-busy="busy" @back="activeInstanceId=null" @play="launch" @stop="stopGame" @account="mcSignIn" @refresh="pollLocal" @browse-mods="navigate('explore')"/>
      <template v-else>
      <p v-if="coreCapabilities?.preview" class="banner notice" style="margin-bottom:18px">Testing build: {{availableLoaders.map(l=>l.name).join(', ')}}. More loader support is being added.</p>
      <div class="library-workspace-header"><div><span class="workspace-kicker">ALL YOUR WORLDS, IN ONE PLACE</span><h1>Your library.</h1><p>Open an instance to manage its mods, files and settings.</p></div><button class="workspace-play" @click="plus"><Plus/> New instance</button></div>
      <div class="library-toolbar"><label class="library-search"><Search/><input v-model="libraryQuery" aria-label="Search your library" placeholder="Search your library…"></label><span class="library-count">{{instances.length}} {{instances.length===1?'instance':'instances'}}</span><div class="library-view-toggle" aria-label="Library view"><button :aria-pressed="libraryView==='grid'" aria-label="Show grid view" @click="libraryView='grid'"><Box/> Grid</button><button :aria-pressed="libraryView==='list'" aria-label="Show list view" @click="libraryView='list'"><Layers3/> List</button></div></div>
      <div class="card account-box" style="margin-bottom:24px"><div><h3>{{minecraft.length?minecraft.find(a=>a.active)?.name||'Minecraft accounts':'Add your Minecraft account'}}</h3><p>Sign in with Microsoft on this device. Your Solara account is separate.</p></div><button :disabled="busy||!engineReady" @click="mcSignIn"><Plus/> Add account</button></div>
      <div v-if="!isDesktop" class="banner notice" style="margin-bottom:20px">App preview. Playing Minecraft needs the installed desktop app.</div>
      <div v-if="!instances.length" class="new-home-empty"><div><span class="empty-library-symbol"><Plus/></span><h3>A fresh start.</h3><p>Pick a version. Give it a name. We will handle the game files and Java.</p></div><button class="workspace-play" @click="plus">Create your first instance <ArrowUpRight/></button></div>
      <div v-else :class="['grid','instance-collection',{'as-list':libraryView==='list'}]"><article v-for="i in visibleInstances" :key="i.id" class="instance-card"><div class="instance-banner-wrap" @click="openInstance(i)"><img :src="instanceArtSrc(i)" alt="" class="instance-banner-img" loading="lazy"><span class="instance-loader-tag" :class="i.loader">{{ i.loader }}</span><span v-if="i.running" class="instance-status-tag running">Running</span></div><div class="details"><button class="library-instance-open" :aria-label="'Open instance '+i.name" @click="openInstance(i)"><span class="instance-letter">{{i.name.slice(0,1).toUpperCase()}}</span><span><h3>{{i.name}}</h3><p>{{i.gameVersion}} · <span class="instance-loader-name">{{i.loader}}</span> · <span :class="{running:i.running}">{{i.running?'Running':i.state}}</span></p></span></button><div class="actions"><button @click="openInstance(i)">Manage <ArrowRight/></button><button v-if="['created','failed','cancelled'].includes(i.state)" :disabled="busy" @click="retryInstall(i)">Retry install</button><button v-else-if="!i.running" class="primary" :disabled="busy||i.state!=='installed'" @click="launch(i)"><Play/> Play</button><button v-else :disabled="busy" @click="stopGame(i)"><Square/> Stop game</button><button title="Edit instance" :disabled="busy" @click="editInstance(i)"><Settings/></button><button title="View game logs" :disabled="busy" @click="instanceLogs(i)"><Terminal/></button><button title="Open instance folder" @click="run(()=>native('open_instance_folder',{id:i.id}))"><FolderOpen/></button></div></div></article></div>
      <div v-if="instances.length&&!visibleInstances.length" class="empty"><Search/><h3>No instances match</h3><p>Try a different name, game version or loader.</p><button @click="libraryQuery=''">Clear search</button></div>
      <div v-if="minecraft.length" class="stack" style="margin-top:25px"><div class="section-title"><h2>Local Minecraft accounts</h2></div><div class="card account-box" v-for="a in minecraft" :key="a.id"><div><h3>{{a.name}}</h3><p>{{a.active?'Selected account':'Saved on this device'}}</p></div><div class="row"><button v-if="!a.active" @click="run(async()=>{await native('select_minecraft_account',{id:a.id});await pollLocal()})">Select</button><button title="Remove this Minecraft account from this device" @click="mcLogout(a.id)"><LogOut/> Remove</button></div></div></div>
      </template>
    </template>
    <template v-if="section==='services'">
      <div class="page-heading"><div><div class="eyebrow" style="margin-bottom:9px">SOLARA SERVICES</div><h1>Your Solara services.</h1><p>Your tools, hosting and help, in one place.</p></div><button @click="refreshPublic"><RefreshCw/> Refresh</button></div>
      <div class="tab-row"><button v-for="f in ['all','tools','hosting','documentation']" :key="f" :class="{selected:serviceFilter===f}" @click="serviceFilter=f">{{f[0].toUpperCase()+f.slice(1)}}</button></div>
      <div v-if="filteredServices.length" class="grid"><article v-for="s in filteredServices" :key="s.id" class="card"><span class="card-icon"><Layers3/></span><h3>{{s.name}}</h3><p>{{s.description}}</p><span class="pill">{{s.status||'Status not reported'}}</span><button v-if="s.url" class="text-link" style="display:block;margin-top:20px" @click="external(s.url)">Open {{s.kind==='web'?'website':'service'}} <ExternalLink/></button></article></div>
      <LoadingCards v-else-if="publicLoading" label="Loading services…"/><div v-else class="empty"><Cloud/><h3>{{snapshot.state==='connected'?'No services in this category':'Service catalogue unavailable'}}</h3><p>{{snapshot.at?'Last public refresh: '+new Date(snapshot.at).toLocaleString():'We haven’t received a public catalogue from the main API yet.'}}</p><button @click="external(links.home)">Browse Solara's website <ArrowUpRight/></button></div>
      <div class="section-title" style="margin-top:30px"><h2>On this device</h2></div><div class="grid"><button class="card" style="text-align:left" @click="navigate('servers');serverTab='local'"><span class="card-icon"><Monitor/></span><h3>Local Server Starter</h3><p>Create and run a Minecraft Java server on your own computer.</p><span class="text-link">Open local servers <ArrowRight/></span></button><button class="card" style="text-align:left" @click="navigate('servers');serverTab='hosted';loadHosted()"><span class="card-icon"><Server/></span><h3>Game Panel Manager</h3><p>Your permitted hosting resources through the main Solara API.</p><span class="text-link">View your servers <ArrowRight/></span></button><button class="card" style="text-align:left" @click="navigate('servers');serverTab='hosting'"><span class="card-icon"><Globe/></span><h3>Local Server Hoster</h3><p>Give a reachable local server a Solara subdomain.</p><span class="text-link">Explore public hosting <ArrowRight/></span></button></div>
    </template>
    <template v-if="section==='servers'">
      <div class="page-heading"><div><div class="eyebrow" style="margin-bottom:9px">YOUR SERVERS</div><h1>Your servers.</h1><p>Local worlds and your Solara hosting, with ownership kept clear.</p></div><button class="primary" @click="plus"><Plus/> Local server</button></div>
      <div class="tab-row"><button v-for="t in [{id:'local',name:'On this device'},{id:'hosted',name:'Solara hosting'},{id:'hosting',name:'Public subdomain'},{id:'network',name:'Server directory'}]" :key="t.id" :class="{selected:serverTab===t.id}" @click="serverTab=t.id;if(t.id==='hosted')loadHosted()">{{t.name}}</button></div>
      <template v-if="serverTab==='local'"><div v-if="!localServers.length" class="server-welcome"><div class="server-welcome-copy"><span class="eyebrow">ON THIS DEVICE</span><h3>Your computer.<br>Your server.</h3><p>Create a Minecraft server on this device. Choose a version, check Java, and bring your friends.</p><button @click="plus"><Plus/> Set up a server</button></div><WorldArt scene="workshop" eager/></div><div v-else class="grid"><article class="card" v-for="s in localServers" :key="s.id"><span class="card-icon"><Server/></span><h3>{{s.name}}</h3><p>{{s.version}} · Port {{s.port}} · {{s.state}}</p><div class="row"><button :disabled="busy" @click="localPower(s,s.state==='running'?'stop':'start')"><Square v-if="s.state==='running'"/><Play v-else/>{{s.state==='running'?'Stop':'Start'}}</button><button :disabled="busy||s.state!=='running'" title="Restart local server" @click="localPower(s,'restart')"><RotateCcw/></button><button title="Local console" @click="localLogs(s)"><Terminal/></button></div></article></div></template>
      <template v-if="serverTab==='hosted'"><div v-if="!account" class="empty"><ShieldCheck/><h3>Sign in to see your servers</h3><p>Sign in to view servers you own or have permission to manage.</p><button @click="signIn"><LogIn/> Sign in to Solara</button></div><div v-else-if="!hosted.length" class="empty"><Server/><h3>No linked servers yet</h3><p>Your servers will appear after your Solara account is linked to the hosting panel.</p><button @click="loadHosted"><RefreshCw/> Refresh servers</button></div><div v-else class="grid"><article class="card" v-for="s in hosted" :key="s.id"><span class="card-icon"><Server/></span><h3>{{s.name}}</h3><p>{{s.state||'State not reported'}}</p><div class="row"><button v-for="a in s.actions||[]" :key="a" :disabled="busy" @click="remotePower(s,a)">{{a}}</button></div><button class="text-link" style="margin-top:17px" @click="external('https://panel.solara-inc.in/server/'+encodeURIComponent(s.id))">Open panel / console <ArrowUpRight/></button></article></div></template>
      <template v-if="serverTab==='hosting'"><div class="split"><div class="card"><span class="card-icon"><Globe/></span><h3>A familiar address for your world.</h3><p>Run your server locally, verify your public endpoint, then request a subdomain under the configured Solara namespace.</p><ol class="step-list"><li>Start a server on your computer.</li><li>Allow inbound traffic and forward your server port.</li><li>Verify your public endpoint and request a name.</li></ol><button class="primary" :disabled="!account" @click="beginAssignment">Request a subdomain <ArrowRight/></button><p v-if="!account" style="margin-top:12px"><button class="text-link" @click="signIn">Sign in to request an assignment</button></p></div><div class="card"><ShieldCheck style="color:var(--accent)"/><h3>Know what becomes public.</h3><p>DNS points players to your public IP address and port. It does not open a firewall, forward a router port or bypass CGNAT.</p><p>Enable hosting only for an endpoint you control. Your address will be visible through public DNS. Solara's VPS is not a gameplay relay.</p><button class="text-link" @click="external(links.support)">Connectivity help <ArrowUpRight/></button></div></div><section v-if="account" class="assignment-section"><div class="section-title"><div><h2>Your server addresses</h2><p>Addresses linked to your Solara account.</p></div><button :disabled="assignmentsLoading||busy" @click="loadAssignments"><RefreshCw/> Refresh addresses</button></div><div v-if="assignmentsError" class="banner error" role="alert" style="margin-bottom:17px">{{assignmentsError}}<span v-if="assignments.length"> Previously loaded addresses are shown below.</span></div><LoadingCards v-if="assignmentsLoading&&!assignments.length" label="Loading your server addresses…"/><div v-else-if="!assignments.length&&!assignmentsError" class="empty"><Globe/><h3>No server addresses yet</h3><p>When a verified address is assigned to your account, you can manage it here.</p><button @click="beginAssignment">Request an address <Plus/></button></div><div v-else class="stack" :aria-busy="assignmentsLoading"><article v-for="item in assignments" :key="item.id" class="card assignment-card"><div class="assignment-summary"><span class="card-icon"><Globe/></span><div><h3>{{item.hostname||item.name}}</h3><p>{{item.endpoint.includes(':')?'['+item.endpoint+']':item.endpoint}}:{{item.port}}</p></div><span class="assignment-status" :data-state="item.status"><span class="dot"></span>{{item.status==='active'?'Active':item.status==='pending'?'Pending':item.status==='error'?'Needs attention':'Status unknown'}}</span></div><p v-if="item.lastError" class="assignment-error">{{item.lastError}}</p><div class="assignment-actions"><small v-if="item.updatedAt">Updated {{new Date(item.updatedAt).toLocaleString()}}</small><button v-if="item.hostname" :disabled="busy||assignmentsLoading" @click="copyAssignment(item)"><Copy/> Copy address</button><button :disabled="busy||assignmentsLoading" @click="editAssignment(item)">Update endpoint</button><button class="danger-text" :disabled="busy||assignmentsLoading" @click="beginRelease(item)">Release address</button></div></article></div></section></template>
      <template v-if="serverTab==='network'"><div class="card network-feature" v-if="snapshot.data?.network?.address"><WorldArt scene="coastal-hamlet" eager/><span class="pill">FEATURED · SOLARA NETWORK</span><h2 style="margin-top:18px">A world worth sharing.</h2><p>{{snapshot.data.network.address}} · Live player counts unavailable unless reported by the API.</p><button @click="run(copyAddress)"><Copy/> Copy address</button></div><div v-else class="empty"><Globe/><h3>Server directory unavailable</h3><p>The featured Solara Network address is supplied by main API configuration. Your saved Minecraft server lists are preserved.</p></div></template>
    </template>
    <template v-if="section==='explore'">
      <p v-if="coreCapabilities?.contentInstall===false" class="banner notice" style="margin-bottom:18px">You can browse content here. Installing it is coming in a later testing build.</p>
      <div class="page-heading"><div><div class="eyebrow" style="margin-bottom:9px">MODS & MODPACKS</div><h1>Find your next favourite.</h1><p>Browse mods, modpacks and more from Modrinth.</p></div></div><form class="search-row" @submit.prevent="searchContent"><input v-model="query" aria-label="Search Modrinth content" placeholder="Search mods, modpacks and more…"><SelectControl v-model="contentType" label="Content type" :options="[{value:'mod',label:'Mods'},{value:'modpack',label:'Modpacks'},{value:'resourcepack',label:'Resource packs'},{value:'shader',label:'Shaders'}]"/><button class="primary" aria-label="Search" :disabled="searching"><Search/> {{searching?'Searching…':'Search'}}</button></form><LoadingCards v-if="searching" label="Searching Modrinth…" :count="6"/><div v-else-if="!results.length&&!hasSearched" class="discovery-welcome"><WorldArt scene="canyon-settlement" eager/><div><span class="eyebrow">SOMETHING NEW TO PLAY</span><h3>Make it your kind<br>of Minecraft.</h3><p>Search for a mod, a modpack or a fresh look for your world.</p></div></div><div v-else-if="!results.length" class="empty"><Search/><h3>No results found</h3><p>Try another name or a different content type.</p></div><div v-else class="grid modrinth-results-grid"><article v-for="r in results" :key="r.project_id" class="card mod-card"><div class="mod-card-top"><span class="card-icon provider-icon mod-avatar"><img v-if="r.icon_url" :src="r.icon_url" :alt="r.title" loading="lazy" referrerpolicy="no-referrer" @error="r.icon_url=null"><Package v-else/></span><div class="mod-card-head"><h3>{{r.title}}</h3><p class="mod-author">by <span>{{r.author}}</span></p></div></div><p class="mod-desc">{{r.description}}</p><div class="mod-card-footer"><div class="mod-card-chips"><span v-if="r.downloads" class="pill download-pill"><Download :size="11"/> {{formatDownloads(r.downloads)}}</span><span class="pill type-pill">{{r.project_type}}</span></div><button class="primary mod-install-btn" :disabled="busy||!engineReady||coreCapabilities?.contentInstall===false" @click="installContent(r)">Install <Download :size="12"/></button></div><button class="text-link mod-provider-link" @click="external(projectUrl(r))">Provider page <ArrowUpRight/></button></article></div>
    </template>
    <template v-if="section==='settings'">
      <div class="page-heading"><div><div class="eyebrow" style="margin-bottom:9px">YOUR PREFERENCES</div><h1>Make Solara yours.</h1><p>Your look, game settings and accounts.</p></div></div><div class="card"><div class="setting-row"><div><h3>Accent colour</h3><p>Pick the colour for your buttons and highlights.</p></div><div class="accent-options" role="group" aria-label="Accent colour"><button v-for="colour in [{hex:'#61c48c',name:'Solara green'},{hex:'#80f5cc',name:'Solara mint'},{hex:'#3dd6f5',name:'Solara cyan'},{hex:'#a6a3ff',name:'Soft iris'},{hex:'#a5cc9a',name:'Sage'},{hex:'#ffb55a',name:'Warm amber'},{hex:'#e4a4b7',name:'Rose'}]" :key="colour.hex" :style="{'--swatch':colour.hex}" :title="colour.name" :aria-label="colour.name" :aria-pressed="preferences.accent===colour.hex" @click="preferences.accent=colour.hex"></button></div></div><div v-if="features.seasons" class="setting-row"><div><h3>Seasonal appearance</h3><p>Use the active Solara event or a quiet neutral theme.</p></div><select v-model="preferences.theme" aria-label="Seasonal theme"><option value="auto">Automatic</option><option value="neutral">Neutral</option></select></div><div class="setting-row"><div><h3>Reduce motion</h3><p>System reduced-motion preferences are always respected.</p></div><input type="checkbox" v-model="preferences.motion" aria-label="Reduce motion"></div><div class="setting-row"><div><h3>Minecraft memory</h3><p>Memory limit in MiB for new instances.</p></div><input style="width:125px" type="number" min="512" max="65536" v-model.number="nativeSettings.memory" aria-label="Maximum memory in MiB"></div><div class="setting-row"><div><h3>Java executable</h3><p>Use a compatible Java installation on this device.</p></div><input style="width:200px" v-model="nativeSettings.javaPath" aria-label="Java executable"></div><div class="setting-row"><div><h3>Discord activity</h3><p>Share “Solara open” or “Minecraft running”. No account or server details.</p></div><input type="checkbox" v-model="nativeSettings.discord" aria-label="Discord activity"></div><button style="margin-top:14px" :disabled="busy||!engineReady" @click="saveNative">Save local preferences</button></div>
      <div class="grid" style="margin-top:18px"><div class="card"><h3>Solara account</h3><p>{{account?'Signed in as '+(account.name||account.username):'Browsing as a guest. Public listings and local Minecraft do not need Solara login.'}}</p><button v-if="account" @click="signOut"><LogOut/> Sign out</button><button v-else @click="signIn"><LogIn/> Sign in</button></div><div class="card"><h3>Updates & what's new</h3><p>Install once. Solara checks for updates and applies them automatically when it is safe.</p><div class="row"><button @click="checkUpdates">Check updates</button><button @click="show('changelog')">Changelog</button></div></div><div class="card"><h3>Experimental access</h3><p>Your Solara account decides which beta features you can use.</p><button :disabled="!account||busy" @click="loadEntitlements">View access</button></div></div><div class="banner" style="margin-top:18px">Solara is independent of Mojang, Microsoft and Modrinth. Built with Solara's independent local Minecraft core (GPL-3.0-only); no warranty. Source and third-party notices are included with the application. <button class="text-link" @click="show('about')">About & licences</button></div>
    </template>
  </div></main>
  <div v-if="['checking','downloading','installing','waiting-for-idle','retry-later'].includes(appUpdate.state)" class="banner" role="status">{{appUpdate.state==='downloading'?'Downloading a launcher update…':appUpdate.state==='installing'?'Applying the update. Solara will reopen automatically.':appUpdate.state==='waiting-for-idle'?'Updates will wait until your games, servers and downloads finish.':appUpdate.state==='retry-later'?'Could not check for updates. Solara will try again later.':'Checking for launcher updates…'}}</div>
  <div class="download-dock"><span class="download-dock-icon"><Download/></span><div><strong>{{jobs.filter(j=>['running','queued','downloading'].includes(j.status)).length?jobs.filter(j=>['running','queued','downloading'].includes(j.status)).length+' downloads in progress':'No active downloads'}}</strong><small>{{jobs.length?jobs.length+' local download records':'Game files and updates will appear here.'}}</small></div><button class="downloads-button" @click="show('downloads')">Downloads <ChevronRight :size="10"/></button></div></div>
  <footer class="app-footer" :inert="modal||bootVisible?true:undefined"><div class="footer-group"><span>SOLARA <span class="optional">LAUNCHER</span></span><span>{{buildInfo.publicVersion||'DEV'}} · {{buildInfo.internalVersion}}</span><span class="connection-status" :data-state="statusTone(snapshot.state)"><span class="dot"/> API {{snapshot.state}}</span><span class="optional" v-if="snapshot.at">Refreshed {{new Date(snapshot.at).toLocaleTimeString()}}</span></div><div class="footer-group"><button v-if="latest" @click="show('changelog')">{{latest.publicVersion}} available</button><button @click="show('changelog')">What's new</button><button class="optional" @click="external(links.docs)">Docs</button><button v-if="links.github" @click="external(links.github)">GitHub</button><button @click="external(links.support)">Support <ArrowUpRight :size="8"/></button></div></footer>

  <Transition name="boot"><section v-if="bootVisible" class="boot-screen" role="dialog" aria-modal="true" aria-labelledby="boot-title" :aria-describedby="startupError?'boot-error':'boot-description'">
    <div class="boot-content"><div class="boot-brand"><img src="/logo.svg" alt="">SOLARA</div><span class="eyebrow">MAKE YOURSELF AT HOME</span><h1 id="boot-title" style="margin-top:15px">{{startupError?'A little help needed.':'Getting things ready.'}}</h1><p id="boot-description">{{startupError?'Your local launcher could not start. You can retry or browse the app.':'Your worlds, mods and tools. All in one place.'}}</p>
      <template v-if="!startupError"><div class="boot-status" role="status" aria-live="polite"><i class="loading-ring" aria-hidden="true"></i>{{!interfaceReady?'Loading your workspace…':'Starting your local launcher…'}}</div><div class="boot-track" role="progressbar" aria-label="Starting Solara"></div><div class="boot-steps"><span><Check v-if="interfaceReady"/><i v-else class="waiting"></i>Interface and artwork</span><span v-if="isDesktop"><Check v-if="engineReady"/><i v-else class="waiting"></i>Local game library</span><span v-else><Check/>Browser preview</span></div></template>
      <template v-else><p id="boot-error" class="boot-error" role="alert">{{startupError}}</p><div class="boot-actions"><button class="primary" @click="retryStartup"><RefreshCw/> Try again</button><button @click="bootVisible=false">Continue to app</button></div></template><small class="boot-fineprint">Your game files stay on your device.<br>Solara services load independently.</small>
    </div>
  </section></Transition>
  <Transition name="dialog"><div v-if="modal" class="modal-shade" @click.self="close" @keydown="trapDialog"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="dialog-title" tabindex="-1"><div class="section-title"><h2 id="dialog-title">{{({'minecraft-login':'Sign in to Minecraft','create-instance':'Create an instance','create-server':'Create a local server','edit-instance':'Instance settings','assignment':'Get a server address','edit-assignment':'Update server endpoint','release-assignment':'Release server address','downloads':'Your downloads','logs':'Local console','account':'Your Solara account','changelog':"What’s new",'install-content':selectedContent?.kind==='modpack'?'Install a modpack':'Add to an instance','beta':'Experimental access','about':'About Solara'} as Record<string,string>)[modal]}}</h2><button class="close" title="Close dialog" aria-label="Close dialog" @click="close"><X/></button></div>
  <div v-if="error" class="banner error" role="alert" style="margin-bottom:18px">{{error}}</div>
  <template v-if="modal==='create-instance'"><p style="font-size:12px">Choose a game version and loader. Each instance keeps its own mods, settings and saves.</p><form @submit.prevent="createInstance"><label class="field">Instance name<input v-model="create.name" placeholder="My next adventure" required maxlength="80"></label><label class="field">Minecraft version<SelectControl v-model="create.gameVersion" label="Minecraft version" :options="versions.map(v=>({value:v.id,label:v.id,hint:v.type}))" :placeholder="versions.length?'Choose a Minecraft version':'Versions load in the desktop app'" searchable/></label><div class="field"><label>Choose a mod loader</label><div class="loader-choices" role="radiogroup" aria-label="Mod loader"><button v-for="l in availableLoaders" :key="l.id" type="button" role="radio" :aria-checked="create.loader===l.id" :class="{chosen:create.loader===l.id}" :title="l.hint" @click="create.loader=l.id"><LoaderMark :loader="l.id"/><strong>{{l.name}}</strong><span class="loader-selected"><Check/></span></button></div></div><label v-if="create.loader!=='vanilla'" class="field">Loader version<SelectControl v-model="create.loaderVersion" label="Loader version" :options="[{value:'',label:loaderLoading?'Checking versions…':'Recommended stable version'},...loaderChoices.map(v=>({value:v.id,label:v.id,hint:v.stable?'Stable':'Preview'}))]" searchable/></label><p v-if="loaderError" class="banner error">{{loaderError}} <button type="button" @click="loadLoaderVersions">Try again</button></p><div class="actions"><button type="button" @click="close">Cancel</button><button class="primary" :disabled="busy||!engineReady||!create.gameVersion||loaderLoading||!!loaderError">{{busy?'Working…':'Create instance'}}</button></div></form></template>
  <form v-if="modal==='edit-instance'" @submit.prevent="saveInstance"><label class="field">Name<input v-model="editForm.name" required maxlength="80"></label><label class="field">Maximum memory (MiB)<input type="number" min="512" max="65536" v-model.number="editForm.memory" required></label><label class="field">Java executable (blank to use Settings)<input v-model="editForm.javaPath"></label><div class="actions"><button type="button" @click="close">Cancel</button><button class="primary" :disabled="busy">Save instance</button></div></form>
  <template v-if="modal==='create-server'"><p style="font-size:12px">Vanilla server files download directly from Mojang. A compatible local Java installation is required.</p><form @submit.prevent="saveServer"><label class="field">Server name<input v-model="serverForm.name" required maxlength="80"></label><label class="field">Minecraft version<SelectControl v-model="serverForm.version" label="Server Minecraft version" :options="versions.filter(v=>v.type==='release').map(v=>({value:v.id,label:v.id}))" placeholder="Choose a server version" searchable/></label><label class="field">Java executable<input v-model="serverForm.javaPath" required></label><div class="split"><label class="field">Memory (MiB)<input type="number" v-model.number="serverForm.memory" min="512" max="65536" required></label><label class="field">Port<input type="number" v-model.number="serverForm.port" min="1024" max="65535" required></label></div><label class="row"><input type="checkbox" v-model="serverForm.eula" required><span>I accept the <a href="https://www.minecraft.net/eula" target="_blank" rel="noopener" style="color:var(--accent)">Minecraft EULA</a> for this server.</span></label><div class="actions"><button type="button" @click="close">Cancel</button><button class="primary" :disabled="busy||!engineReady||!serverForm.eula||!serverForm.version">Set up server</button></div></form></template>
  <template v-if="modal==='assignment'||modal==='edit-assignment'"><p style="font-size:12px">{{modal==='edit-assignment'?'Update the verified public endpoint for '+(assignmentTarget?.hostname||assignmentTarget?.name)+'.':'Use a public IP address you control. Your router and firewall must allow players to connect.'}}</p><form @submit.prevent="saveAssignment"><template v-if="modal==='assignment'"><label class="field">Requested name<input v-model="assignment.name" pattern="[a-z0-9][a-z0-9-]{1,30}[a-z0-9]" required></label><label class="field">Local server<SelectControl v-model="assignment.serverId" label="Local server" :options="localServers.map(s=>({value:s.id,label:s.name}))" placeholder="Choose a server"/></label><p v-if="!localServers.length" class="banner">Create a local server on this device before requesting an address.</p></template><label class="field">Public IP address<input v-model="assignment.endpoint" placeholder="Your public IPv4 or IPv6" required maxlength="45"></label><label class="field">Public port<input type="number" min="1024" max="65535" v-model.number="assignment.port" required></label><p class="banner">Control of this endpoint must be verified before the address can be changed.</p><label class="row"><input type="checkbox" required v-model="assignment.consent"><span>I control this endpoint and understand its IP address becomes public.</span></label><div class="actions"><button type="button" @click="close">Cancel</button><button class="primary" :disabled="busy||!account||!assignment.consent||(modal==='assignment'&&!assignment.serverId)">{{busy?'Saving…':modal==='edit-assignment'?'Update endpoint':'Request assignment'}}</button></div></form></template>
  <template v-if="modal==='release-assignment'"><p style="font-size:13px">Release <strong>{{assignmentTarget?.hostname||assignmentTarget?.name}}</strong>?</p><p style="font-size:12px">Players will no longer be able to join using this address. Your local server and its files will stay on your device.</p><form @submit.prevent="releaseAssignment"><label class="row"><input type="checkbox" v-model="releaseConsent" required><span>I understand this removes the server address.</span></label><div class="actions"><button type="button" @click="close">Keep address</button><button class="danger-button" :disabled="busy||!releaseConsent">{{busy?'Releasing…':'Release address'}}</button></div></form></template>
  <template v-if="modal==='minecraft-login'&&minecraftPrompt"><p>Open Microsoft's sign-in page and enter this code. Only continue if Microsoft shows the Solara app you expected.</p><div class="minecraft-device-code" aria-label="Your one-time Microsoft sign-in code">{{minecraftPrompt.code}}</div><p class="muted">Your password stays on Microsoft's website. This code expires soon.</p><div class="actions"><button @click="close">Cancel sign-in</button><button class="primary" @click="external(minecraftPrompt.url)">Open Microsoft sign-in <ArrowUpRight/></button></div></template>
  <template v-if="modal==='downloads'"><div v-if="!jobs.length" class="empty"><Download/><h3>Nothing in the queue</h3><p>Real download activity appears here as you install game files, content or local servers.</p></div><div v-for="j in jobs" :key="j.id" class="download-item"><div class="section-title"><h3>{{j.name}}</h3><span class="pill">{{j.status}}</span></div><progress v-if="typeof j.progress==='number'&&!j.total" :value="j.progress" :max="1"></progress><progress v-if="j.total" :value="j.downloaded" :max="j.total"></progress><div v-if="['running','queued','downloading'].includes(j.status)&&typeof j.progress!=='number'&&!j.total" class="boot-track job-indeterminate" role="progressbar" :aria-label="'Installing '+j.name"></div><p>{{j.detail||''}} <span v-if="j.total">{{Math.round(j.downloaded/1048576)}} / {{Math.round(j.total/1048576)}} MiB</span><span v-if="j.speed"> · {{(j.speed/1048576).toFixed(1)}} MiB/s</span></p><div class="row"><button v-for="a in j.actions||[]" :key="a" :disabled="busy&&a!=='cancel'" @click="downloadAction(j,a)">{{a}}</button></div></div></template>
  <template v-if="modal==='logs'"><p style="font-size:11px">These logs stay on your device. Account tokens are hidden.</p><pre class="console">{{logs||'No messages yet.'}}</pre><form v-if="selectedLog" class="row" style="margin-top:12px" @submit.prevent="run(async()=>{await native('local_server_command',{id:selectedLog.id,command:query});query='';logs=await native('local_server_logs',{id:selectedLog.id})})"><input aria-label="Local server command" v-model="query" maxlength="500" placeholder="Local server command"><button :disabled="busy">Send</button></form></template>
  <template v-if="modal==='account'"><div class="card"><h3>{{account?.name||account?.username}}</h3><p>Solara identity and service permissions. Your Microsoft/Minecraft account is managed separately on this device.</p><button @click="signOut();close()"><LogOut/> Sign out of Solara</button></div><button class="text-link" style="margin-top:20px" @click="external('https://auth.solara-inc.in')">Manage your central account <ArrowUpRight/></button></template>
  <template v-if="modal==='changelog'"><div v-if="!publicReleases.length" class="empty"><GitBranch/><h3>The first release is taking shape</h3><p>No published release metadata is available. Release notes will appear here when the first verified build is published.</p></div><article v-for="r in publicReleases" :key="r.buildId" class="download-item"><h3>{{r.publicVersion}} · {{r.state}}</h3><p>{{r.notes}}</p><small class="muted">{{r.publishedAt?new Date(r.publishedAt).toLocaleDateString(): 'Not published'}}</small></article><p style="margin-top:18px">Updates download and install automatically when your games, servers and downloads are finished.</p></template>
  <template v-if="modal==='install-content'&&selectedContent"><div class="install-project"><span class="card-icon provider-icon"><img v-if="selectedContent.project.icon_url" :src="selectedContent.project.icon_url" alt="" referrerpolicy="no-referrer" @error="selectedContent.project.icon_url=null"><Package v-else/></span><div><h3>{{selectedContent.project.title}}</h3><p>{{selectedContent.kind==='modpack'?'A new instance with its own mods, settings and saves.':'Choose the instance you want to change.'}}</p></div></div><form @submit.prevent="confirmInstall">
    <template v-if="selectedContent.kind==='modpack'"><div v-if="packVersionsLoading" class="loading-caption" role="status"><i class="loading-ring" aria-hidden="true"></i>Loading modpack versions…</div><div v-else-if="selectedContent.error" class="banner error" role="alert">{{selectedContent.error}} <button type="button" class="text-link" @click="loadPackVersions">Try again</button></div><label v-else-if="selectedContent.versions.length" class="field">Modpack version<SelectControl v-model="selectedContent.versionId" label="Modpack version" :options="selectedContent.versions.map((v:any)=>({value:v.id,label:v.name+' · '+v.type,hint:'Minecraft '+v.games+(v.loaders?' · '+v.loaders:'')}))" searchable/></label><div v-else class="banner">No supported modpack files are available. <button type="button" class="text-link" @click="loadPackVersions">Refresh versions</button></div><p class="banner">This creates a separate instance. Your existing worlds and mods stay in place.</p></template>
    <template v-else><label class="field">Install into<SelectControl v-model="selectedContent.instanceId" label="Install into" :options="eligibleTargetInstances.map(i=>({value:i.id,label:i.name,hint:i.gameVersion+' · '+i.loader}))"/></label><p style="font-size:12px">The launcher checks compatible versions and required dependencies before adding content.</p></template>
    <div class="actions"><button type="button" @click="close">Cancel</button><button class="primary" :disabled="busy||!engineReady||packVersionsLoading||(selectedContent.kind==='modpack'?!selectedContent.versionId:!selectedContent.instanceId)">{{busy?'Installing…':selectedContent.kind==='modpack'?'Install modpack':'Install content'}}</button></div></form></template>
  <template v-if="modal==='beta'"><p v-if="!entitlements.length" class="banner">Your account has no active beta features yet.</p><div v-for="e in entitlements" :key="e.feature" class="download-item"><h3>{{e.feature}}</h3><p>{{e.active?'Active':'Expired or revoked'}} · {{e.expiresAt||'No expiry reported'}}</p></div></template>
  <template v-if="modal==='about'"><p>Solara Launcher is an independent desktop app for Minecraft Java and Solara services. This testing build uses Solara's own local Minecraft core.</p><p style="font-size:12px">The interface and native source are GPL-3.0-only. Required library and font notices are included in LICENSE and THIRD_PARTY_NOTICES.md. Solara is not affiliated with Mojang or Microsoft. A licensed Minecraft Java account is required to play.</p></template>
  </section></div></Transition><Transition name="toast"><div v-if="message" class="toast" role="status"><Check/><span>{{message}}</span><button class="toast-close" aria-label="Dismiss notification" @click="message=''"><X/></button></div></Transition>
</div>
</template>
